<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --card: #ffffff;
        --text: #182033;
        --muted: #5e6a7d;
        --border: #d9e1ec;
        --primary: #2563eb;
        --primary-dark: #1d4ed8;
        --ring: rgba(37, 99, 235, 0.28);
        --shadow: 0 24px 70px rgba(24, 32, 51, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 32px 16px;
        background:
          radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 34rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      .page-shell {
        width: min(100%, 560px);
      }

      .form-card {
        padding: clamp(24px, 5vw, 40px);
        border: 1px solid rgba(217, 225, 236, 0.9);
        border-radius: 28px;
        background: rgba(255, 255, 255, 0.94);
        box-shadow: var(--shadow);
        backdrop-filter: blur(14px);
      }

      .eyebrow {
        margin: 0 0 10px;
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 6vw, 3rem);
        line-height: 1.08;
        letter-spacing: -0.045em;
      }

      .intro {
        margin: 14px 0 30px;
        color: var(--muted);
        font-size: 1rem;
      }

      .form-field {
        margin: 0 0 28px;
      }

      .question-fieldset {
        padding: 0;
        border: 0;
      }

      legend {
        margin-bottom: 14px;
        padding: 0;
        font-size: 1.08rem;
        font-weight: 700;
      }

      .radio-group {
        display: grid;
        gap: 12px;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 12px;
        padding: 16px;
        border: 1px solid var(--border);
        border-radius: 18px;
        background: #ffffff;
        color: var(--text);
        cursor: pointer;
        transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
      }

      .radio-option:hover {
        border-color: #9db5da;
        transform: translateY(-1px);
      }

      .radio-option:has(input:focus-visible) {
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

      .radio-option:has(input:checked) {
        border-color: var(--primary);
        box-shadow: 0 10px 28px rgba(37, 99, 235, 0.14);
      }

      input[type="radio"] {
        width: 1.18rem;
        height: 1.18rem;
        margin: 0;
        accent-color: var(--primary);
        flex: 0 0 auto;
      }

      .option-text {
        font-weight: 650;
      }

      .submit-button {
        width: 100%;
        min-height: 52px;
        border: 0;
        border-radius: 16px;
        background: var(--primary);
        color: #ffffff;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 16px 32px rgba(37, 99, 235, 0.24);
        transition: background 180ms ease, transform 180ms ease, box-shadow 180ms ease;
      }

      .submit-button:hover {
        background: var(--primary-dark);
        transform: translateY(-1px);
        box-shadow: 0 18px 38px rgba(37, 99, 235, 0.3);
      }

      .submit-button:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: 4px;
      }
    </style>
  </head>
  <body>
    <main id="root" class="page-shell"></main>

    <script>
      const notificationOptions = ["Email", "SMS", "Push Notifications"];

      function RadioOption({ id, name, value, label, required }) {
        return `
          <label class="radio-option" for="${id}">
            <input id="${id}" type="radio" name="${name}" value="${value}" ${required ? "required" : ""}>
            <span class="option-text">${label}</span>
          </label>
        `;
      }

      function NotificationQuestion() {
        const name = "notification-preference";
        const options = notificationOptions
          .map((option, index) =>
            RadioOption({
              id: `${name}-${index}`,
              name,
              value: option.toLowerCase().replaceAll(" ", "-"),
              label: option,
              required: index === 0
            })
          )
          .join("");

        return `
          <div class="form-field">
            <fieldset class="question-fieldset">
              <legend>How do you prefer to receive notifications?</legend>
              <div class="radio-group">
                ${options}
              </div>
            </fieldset>
          </div>
        `;
      }

      function PreferencesForm() {
        return `
          <form class="form-card" action="#" method="post">
            <p class="eyebrow">Preferences</p>
            <h1>Stay in the loop</h1>
            <p class="intro">Choose the channel that works best for timely product updates and account alerts.</p>
            ${NotificationQuestion()}
            <button class="submit-button" type="submit">Save preference</button>
          </form>
        `;
      }

      function App() {
        return PreferencesForm();
      }

      document.getElementById("root").innerHTML = App();
    </script>
  </body>
</html>
